/bin/bash -lc "cat > .tmp/tracks.py <<'PY'
import cv2,numpy as np
A=np.load('source_pixels.npz')['rgb']
for typ in ('red','blue'):
 pred=np.array([140.,68.]) if typ=='red' else np.array([168.,59.])
 print('\\n',typ)
 for i,im in enumerate(A):
  hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV); H,S,V=[hsv[:,:,k] for k in range(3)]
  if typ=='red': m=((H<12)|(H>172))&(S>100)&(V>120)
  else: m=(H>105)&(H<140)&(S>75)&(V>75)
  # local table central
  yy,xx=np.ogrid[:144,:256]; m &= (xx>=70)&(xx<180)&(yy>=45)&(yy<100)
  n,l,st,c=cv2.connectedComponentsWithStats(m.astype('uint8'))
  opts=[]
  for j in range(1,n):
   x,y,w,h,a=st[j]
   if a>=3 and w<=20 and h<=15:
    dist=np.linalg.norm(c[j]-pred)
    opts.append((dist,-a,j))
  if opts:
   j=min(opts)[2]; ctr=c[j]; pred=.55*pred+.45*ctr
   print(f'{i:02d} {ctr[0]:5.1f} {ctr[1]:5.1f} area{st[j,4]:2d}',end=' | ')
  else: print(f'{i:02d} ----',end=' | ')
  if i%4==3:print()
PY
python .tmp/tracks.py"

